param([string]$ProjectRoot = (Join-Path $PSScriptRoot '..'), [string]$IosRoot = (Join-Path $PSScriptRoot '..\..\doubleTriangle\Packages\WildforceShared\Sources\WildforceShared\Models\Enums'), [string]$IosCatalog = (Join-Path $PSScriptRoot '..\..\doubleTriangle\Packages\WildforceShared\Sources\WildforceShared\Resources\Localizable.xcstrings'))
$ErrorActionPreference='Stop'
$sources=[ordered]@{
  LifestyleLevel='User\Lifestyle.swift'; FitnessGoal='User\Goal.swift'; TrainingLevel='User\TrainingLevel.swift'
  TrainingSplitPreference='User\TrainingSplitPreference.swift'; BodyCompositionPhase='User\BodyCompositionPhase.swift'
  GymType='User\GymType.swift'; Equipment='User\Equipment.swift'; EquipmentCategory='User\EquipmentCategory.swift'; MovementRestriction='User\MovementRestrictions.swift'
  Gender='User\Gender.swift'; WorkoutFocus='Workouts\WorkoutFocus.swift'
}
[xml]$sheet=Get-Content (Join-Path $ProjectRoot 'core\designsystem\src\main\res\values\sheet_translations.xml') -Raw -Encoding utf8
$values=@{};foreach($item in $sheet.resources.string){$values[$item.name]=$item.'#text'}
$ios=Get-Content $IosCatalog -Raw -Encoding utf8 | ConvertFrom-Json -AsHashtable
$localFallbacks=Get-Content (Join-Path $PSScriptRoot 'onboarding-local-fallbacks.json') -Raw -Encoding utf8 | ConvertFrom-Json -AsHashtable
$fallbacks=[ordered]@{}
$lines=[System.Collections.Generic.List[string]]::new();$lines.Add('package io.codepassion.doubletriangle.feature.onboarding');$lines.Add('');$lines.Add('// Generated by scripts/sync-onboarding-sheet-map.ps1. Do not edit manually.');$lines.Add('internal val onboardingSheetResources: Map<String, Int> = mapOf(')
$count=0
foreach($kind in $sources.Keys){
 $swift=Get-Content (Join-Path $IosRoot $sources[$kind]) -Raw -Encoding utf8
 foreach($prop in @('englishName','description')){
  $section=[regex]::Match($swift,'(?:public\s+)?var\s+'+$prop+'\s*:\s*String\s*\{([\s\S]*?)\n\s*\}')
  if(!$section.Success){continue}
  foreach($match in [regex]::Matches($section.Groups[1].Value,'case\s+\.([A-Za-z][A-Za-z0-9]*)\s*:\s*(?:return\s+)?"([^"\\\r\n]+)"')){
   $value=$match.Groups[2].Value;$name=[regex]::Replace($value.Replace('-','_').Replace(' ','_').ToLowerInvariant(),'[^a-z0-9_]','_')
   $english=if($name -and $values.ContainsKey($name)){$values[$name].Replace("\'", "'").Replace('\"','"').Replace('\\','\')}else{$null}
   if($english -ine $value){
    $name='ios_onboarding_'+[Convert]::ToHexString([System.Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($value))).Substring(0,16).ToLowerInvariant()
    $fallbacks[$name]=$value
   }
   $id=$match.Groups[1].Value;$lines.Add("    `"${kind}:$id`:$prop`" to io.codepassion.doubletriangle.core.designsystem.R.string.``$name``,");$count++
  }
 }
}
$lines.Add(')');$output=Join-Path $ProjectRoot 'feature\onboarding\src\main\java\io\codepassion\doubletriangle\feature\onboarding\OnboardingSheetResources.kt';[IO.File]::WriteAllLines($output,$lines,[Text.UTF8Encoding]::new($false))
$locales=[ordered]@{en='values';ca='values-ca';de='values-de';es='values-es';fr='values-fr';it='values-it';ja='values-ja';nl='values-nl';pt='values-pt';'zh-Hans'='values-zh-rCN'}
foreach($locale in $locales.Keys){
 $resourceLines=[System.Collections.Generic.List[string]]::new();$resourceLines.Add('<?xml version="1.0" encoding="utf-8"?>');$resourceLines.Add('<!-- Generated iOS fallbacks for onboarding keys absent from the Sheet. -->');$resourceLines.Add('<resources>')
 foreach($name in $fallbacks.Keys){
  $key=$fallbacks[$name];$value=$null
  if($ios.strings.ContainsKey($key) -and $ios.strings[$key].localizations -and $ios.strings[$key].localizations.ContainsKey($locale)){$value=$ios.strings[$key].localizations[$locale].stringUnit.value}
  if ([string]::IsNullOrWhiteSpace($value) -and $localFallbacks.ContainsKey($locale) -and $localFallbacks[$locale].ContainsKey($name)) { $value = $localFallbacks[$locale][$name] }
  if([string]::IsNullOrWhiteSpace($value) -or $value -match '^#(?:ERROR|REF|N/A|VALUE|DIV/0|NAME|NUM|NULL)[!?]?$'){if($locale -eq 'en'){$value=$key}else{continue}}
  $value=$value.Replace('\','\\').Replace("`r`n",'\n').Replace("`n",'\n').Replace("'","\'").Replace('"','\"');$value=[Security.SecurityElement]::Escape($value)
  $resourceLines.Add("    <string name=`"$name`" formatted=`"false`">$value</string>")
 }
 $resourceLines.Add('</resources>');$directory=Join-Path $ProjectRoot "core\designsystem\src\main\res\$($locales[$locale])";[IO.File]::WriteAllLines((Join-Path $directory 'ios_onboarding_fallbacks.xml'),$resourceLines,[Text.UTF8Encoding]::new($false))
}
Write-Output "Mapped $count onboarding names and descriptions; $($fallbacks.Count) use iOS fallback keys absent from the Sheet."
